rules.logic:
if (element._ytCustomButtonsAdded) return;
element._ytCustomButtonsAdded = true;

var titleWrapper = element.shadowRoot ? element.shadowRoot.querySelector('#title-wrapper') : null;
if (!titleWrapper) return;

var menuDiv = titleWrapper.querySelector('#menu');
if (!menuDiv) return;

var buttonRow = document.createElement('div');
buttonRow.style.cssText = 'display:flex;gap:4px;margin-top:4px;align-items:center;';

// Subscribe button
var subBtn = document.createElement('button');
subBtn.style.cssText = 'background:#212121;color:#fff;border:none;padding:6px 12px;border-radius:18px;font-size:13px;font-weight:500;cursor:pointer;display:flex;align-items:center;gap:4px;white-space:nowrap;line-height:1.2;';
subBtn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" height="16" viewBox="0 0 24 24" width="16" focusable="false" aria-hidden="true" style="pointer-events:none;display:inline-block;width:16px;height:16px;fill:#fff;"><path d="M18 1H6a2 2 0 00-2 2h16a2 2 0 00-2-2Zm3 4H3a2 2 0 00-2 2v13a2 2 0 002 2h18a2 2 0 002-2V7a2 2 0 00-2-2ZM3 20V7h18v13H3Zm13-6.5L10 10v7l6-3.5Z"/></svg> Subscribe';

// Add to playlist button
var saveBtn = document.createElement('button');
saveBtn.style.cssText = 'background:#212121;color:#fff;border:none;padding:6px 12px;border-radius:18px;font-size:13px;font-weight:500;cursor:pointer;display:flex;align-items:center;gap:4px;white-space:nowrap;line-height:1.2;';
saveBtn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" height="16" viewBox="0 0 24 24" width="16" focusable="false" aria-hidden="true" style="pointer-events:none;display:inline-block;width:16px;height:16px;fill:#fff;"><path d="M14 10H2v2h12v-2Zm0-4H2v2h12V6Zm4 8v-4l5 4-5 4v-3.05V14h-9v2h9Zm-4 4H2v2h12v-2Z"/></svg> Add to playlist';

// Get video ID from thumbnail link
var thumbLink = element.shadowRoot ? element.shadowRoot.querySelector('ytd-thumbnail a#thumbnail') : null;
var videoId = '';
if (thumbLink) {
  var href = thumbLink.getAttribute('href') || '';
  var match = href.match(/[?&]v=([a-zA-Z0-9_-]+)/);
  if (match) videoId = match[1];
}

// Get channel handle from channel link
var channelLink = element.shadowRoot ? element.shadowRoot.querySelector('#channel-info a#channel-thumbnail') : null;
var channelId = '';
if (channelLink) {
  var chHref = channelLink.getAttribute('href') || '';
  if (chHref.includes('/@')) {
    channelId = chHref.split('/@')[1];
  }
}

subBtn.addEventListener('mouseenter', function() { subBtn.style.background = '#3f3f3f'; });
subBtn.addEventListener('mouseleave', function() { subBtn.style.background = '#212121'; });
saveBtn.addEventListener('mouseenter', function() { saveBtn.style.background = '#3f3f3f'; });
saveBtn.addEventListener('mouseleave', function() { saveBtn.style.background = '#212121'; });

subBtn.addEventListener('click', function(e) {
  e.preventDefault();
  e.stopPropagation();
  if (channelId) {
    window.open('https://www.youtube.com/channel/' + channelId, '_blank');
  } else {
    var info = element.shadowRoot ? element.shadowRoot.querySelector('#channel-info a') : null;
    if (info) window.open(info.href, '_blank');
  }
});

saveBtn.addEventListener('click', function(e) {
  e.preventDefault();
  e.stopPropagation();
  if (videoId) {
    window.open('https://www.youtube.com/playlist?list=PLxx&add=' + videoId, '_blank');
  }
});

buttonRow.appendChild(subBtn);
buttonRow.appendChild(saveBtn);
titleWrapper.insertBefore(buttonRow, menuDiv.nextSibling);
